use std::{env, fs, io::{self, Cursor}, path::{Path, PathBuf}, process::{Command, ExitCode, Stdio}};
use serde_json::{json, Value};
use zip::ZipArchive;

// Generated by CI; the user needs no network for the editor itself.
static PAYLOAD: &[u8] = include_bytes!("../../payload.zip");
const BUILD: &str = env!("CARGO_PKG_VERSION");

fn extract(root: &Path) -> io::Result<()> {
    let marker = root.join(".ready");
    if marker.is_file() { return Ok(()); }
    fs::create_dir_all(root)?;
    let mut archive = ZipArchive::new(Cursor::new(PAYLOAD)).map_err(io::Error::other)?;
    for index in 0..archive.len() {
        let mut file = archive.by_index(index).map_err(io::Error::other)?;
        let path = root.join(file.enclosed_name().ok_or_else(|| io::Error::other("Invalid archive path"))?);
        if file.is_dir() { fs::create_dir_all(path)?; continue; }
        if let Some(parent) = path.parent() { fs::create_dir_all(parent)?; }
        io::copy(&mut file, &mut fs::File::create(path)?)?;
    }
    fs::write(marker, BUILD)
}

fn system_python() -> Option<PathBuf> {
    // Avoid Windows Store aliases: executing them can launch a Store popup.
    let paths: Vec<_> = env::split_paths(&env::var_os("PATH").unwrap_or_default()).collect();
    for dir in &paths {
        if dir.to_string_lossy().to_ascii_lowercase().contains("windowsapps") { continue; }
        for name in ["python.exe", "python3.exe"] {
            let path=dir.join(name);
            if path.is_file() && Command::new(&path).args(["-c", "import sys; assert sys.version_info >= (3,10)"]).stdout(Stdio::null()).stderr(Stdio::null()).status().map(|s| s.success()).unwrap_or(false) { return Some(path); }
        }
    }
    // Python installed through the official launcher may not be on PATH.
    for dir in &paths {
        let py=dir.join("py.exe");
        if !py.is_file() { continue; }
        if let Ok(out)=Command::new(py).args(["-3", "-c", "import sys; assert sys.version_info >= (3,10); print(sys.executable)"]).stderr(Stdio::null()).output() {
            if out.status.success() { let path=PathBuf::from(String::from_utf8_lossy(&out.stdout).trim()); if path.is_file() { return Some(path); } }
        }
    }
    None
}

fn file_uri(path: &Path) -> String {
    let p=path.to_string_lossy().replace('\\', "/");
    let p=p.strip_prefix("//?/").unwrap_or(&p);
    let mut out=if p.starts_with("//") { "file:".to_string() } else { "file:///".to_string() };
    for byte in p.bytes() {
        if byte.is_ascii_alphanumeric() || b"/-._~:".contains(&byte) { out.push(byte as char); }
        else { out.push_str(&format!("%{byte:02X}")); }
    }
    out
}
fn checksum(bytes: &[u8]) -> String {
    let mut hash=0xcbf29ce484222325u64;
    for b in bytes { hash^=*b as u64; hash=hash.wrapping_mul(0x100000001b3); }
    format!("{hash:016x}")
}
fn prepare(runtime: &Path, target: &Path, python: Option<&Path>, missing: &[String]) -> Result<(), Box<dyn std::error::Error>> {
    fs::create_dir_all(target.join("themes"))?;
    fs::create_dir_all(target.join("fresh-kit-runtime"))?;
    let root=runtime.join("kit");
    for name in ["bridge.py", "file_ops.py"] { fs::copy(root.join("runtime").join(name),target.join("fresh-kit-runtime").join(name))?; }
    let theme=target.join("themes").join("gruvbox-design.json");
    if !theme.exists() { fs::copy(root.join("config/themes/gruvbox-design.json"),&theme)?; }
    let meta_path=target.join("fresh-kit-managed.json");
    let previous: Value=fs::read(&meta_path).ok().and_then(|b| serde_json::from_slice(&b).ok()).unwrap_or(json!({}));
    let python_path=python.map(|p|p.to_string_lossy().to_string()).unwrap_or_else(||"python".to_string());
    let config_path=target.join("config.json");
    let template_config=root.join("config/config.json");
    let mut config: Value=serde_json::from_slice(&fs::read(if config_path.exists() { &config_path } else { &template_config })?)?;
    if config["theme"]=="__FRESH_KIT_THEME__" { config["theme"]=json!(file_uri(&theme)); }
    let current=config["lsp"]["python"][0]["command"].as_str().unwrap_or("");
    if current=="__FRESH_KIT_PYLSP__" || previous["python"].as_str()==Some(current) {
        config["lsp"]["python"][0]["command"]=json!(python_path);
        config["lsp"]["python"][0]["args"]=json!(["-m","pylsp"]);
    }
    fs::write(config_path,serde_json::to_vec_pretty(&config)?)?;
    let init_path=target.join("init.ts");
    let current=fs::read(&init_path).ok().map(|b|checksum(&b));
    if current.is_none() || previous["init_hash"].as_str()==current.as_deref() {
        let template=fs::read_to_string(root.join("config/init.ts"))?;
        let mut output=template.replace("__FRESH_KIT_PYTHON__", &serde_json::to_string(&python_path)?);
        let notice = if python.is_none() { Some("Python 3.10+ not found; Python features are unavailable".to_string()) }
            else if !missing.is_empty() { Some(format!("Missing Python packages: {}. Install python-lsp-server debugpy Send2Trash", missing.join(", "))) }
            else { None };
        if let Some(message)=notice {
            output.push_str(&format!("\nregisterHandler(\"fresh_kit_python_notice\",()=>editor.setStatus({}));\neditor.setTimeout(1800,\"fresh_kit_python_notice\");\n",serde_json::to_string(&message)?));
        }
        fs::write(&init_path,output.as_bytes())?;
        fs::write(meta_path,serde_json::to_vec(&json!({"init_hash":checksum(output.as_bytes()),"python":python_path}))?)?;
    }
    Ok(())
}
fn run() -> Result<i32, Box<dyn std::error::Error>> {
    let base=PathBuf::from(env::var_os("LOCALAPPDATA").ok_or("LOCALAPPDATA is not set")?).join("FreshKit");
    let runtime=base.join("runtime").join(BUILD); let profile=base.join("profile");
    extract(&runtime)?; fs::create_dir_all(&profile)?;
    let self_test=env::args().any(|a|a=="--self-test");
    let python=if self_test && env::var_os("FRESH_KIT_TEST_NO_PYTHON").is_some() {None} else {system_python()};
    let missing:Vec<String>=if let Some(path)=&python {
        let probe=Command::new(path).args(["-c", "import importlib.util; print(','.join(x for x in ('pylsp','debugpy','send2trash') if importlib.util.find_spec(x) is None))"]).stderr(Stdio::null()).output();
        match probe { Ok(out) if out.status.success()=>String::from_utf8_lossy(&out.stdout).trim().split(',').filter(|s|!s.is_empty()).map(str::to_owned).collect(), _=>vec!["package check failed".into()] }
    } else {vec![]};
    prepare(&runtime,&profile.join("fresh"),python.as_deref(),&missing)?;
    if self_test {
        let status=Command::new(runtime.join("fresh.exe")).arg("--version").status()?;
        return Ok(status.code().unwrap_or(1));
    }
    if python.is_none() { eprintln!("Python 3.10+ was not found; Python-related features will be unavailable."); }
    let mut command=Command::new(runtime.join("fresh.exe"));
    command.env("FRESH_KIT_CONFIG_DIR",profile.join("fresh"));
    // Keep the patched embedded build intact; updates ship as new Kit executables.
    command.arg("--no-upgrade-check");
    command.args(env::args_os().skip(1));
    Ok(command.status()?.code().unwrap_or(1))
}
fn main() -> ExitCode {
    match run() {
        Ok(code)=>ExitCode::from(code.clamp(0,255) as u8),
        Err(error)=>{eprintln!("Fresh Kit: {error}");eprintln!("Press Enter to close.");let _=io::stdin().read_line(&mut String::new());ExitCode::FAILURE}
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn uri_escapes_spaces_and_non_ascii() {
        assert_eq!(file_uri(Path::new("C:\\Users\\A B\\测试.json")),"file:///C:/Users/A%20B/%E6%B5%8B%E8%AF%95.json");
    }
    #[test]
    fn preserves_custom_init_and_config() {
        let dir=env::temp_dir().join(format!("fresh-kit-unit-{}",std::process::id()));
        let _=fs::remove_dir_all(&dir);let runtime=dir.join("runtime");let target=dir.join("profile");
        for p in ["kit/runtime","kit/config/themes"] {fs::create_dir_all(runtime.join(p)).unwrap();}
        for p in ["bridge.py","file_ops.py"] {fs::write(runtime.join("kit/runtime").join(p),"x").unwrap();}
        fs::write(runtime.join("kit/config/themes/gruvbox-design.json"),"{}").unwrap();
        fs::write(runtime.join("kit/config/config.json"),r#"{"theme":"__FRESH_KIT_THEME__","lsp":{"python":[{"command":"__FRESH_KIT_PYLSP__"}]}}"#).unwrap();
        fs::write(runtime.join("kit/config/init.ts"),"const p=__FRESH_KIT_PYTHON__;").unwrap();
        prepare(&runtime,&target,None,&[]).unwrap();
        assert!(fs::read_to_string(target.join("init.ts")).unwrap().contains("Python 3.10+ not found"));
        fs::write(target.join("init.ts"),"user custom init").unwrap();
        let mut cfg:Value=serde_json::from_slice(&fs::read(target.join("config.json")).unwrap()).unwrap();
        cfg["theme"]=json!("my-theme");fs::write(target.join("config.json"),serde_json::to_vec(&cfg).unwrap()).unwrap();
        prepare(&runtime,&target,Some(Path::new("python.exe")),&[]).unwrap();
        assert_eq!(fs::read_to_string(target.join("init.ts")).unwrap(),"user custom init");
        let cfg:Value=serde_json::from_slice(&fs::read(target.join("config.json")).unwrap()).unwrap();assert_eq!(cfg["theme"],"my-theme");
        fs::remove_dir_all(dir).unwrap();
    }
}
